'use client';

import { useLocale, useTranslations } from 'next-intl';
import { useState } from 'react';
import Image from 'next/image';
import { BarChart3, CheckCircle2, Circle, CheckSquare2, Square, Plus, Loader2, Users } from 'lucide-react';
import type { CommunityPoll, CommunityPollOption } from '@/types/community-social';
import { communitiesApi } from '@/features/communities/api';
import { tournamentsApi } from '@/features/tournaments/api';
import toast from 'react-hot-toast';
import { useUserProfileModalStore } from '@/lib/zustand/userProfileModalStore';
import { useAuthStore } from '@/lib/zustand/authStore';
import { cn } from '@/utils/cn';

type PollOptionKind = 'positive' | 'neutral' | 'negative' | 'other';

const getPollOptionKind = (optionText: string): PollOptionKind => {
  const normalized = optionText
    .replace(/[✅⏳❌]/gu, '')
    .trim()
    .toLocaleLowerCase('vi-VN');

  if (
    optionText.includes('✅') ||
    ['có tham gia', 'đăng ký', 'yes', 'register', 'join'].includes(normalized)
  ) {
    return 'positive';
  }

  if (
    optionText.includes('⏳') ||
    ['chưa chắc chắn', 'có thể', 'maybe', 'not sure'].includes(normalized)
  ) {
    return 'neutral';
  }

  if (
    optionText.includes('❌') ||
    ['bận', 'không tham gia', 'no', 'busy', 'cannot join'].includes(normalized)
  ) {
    return 'negative';
  }

  return 'other';
};

