import { expect, test } from '@playwright/test';

import { fulfillApi } from './support/organizer-manage';

const organizer = {
  id: 'synthetic-ai-modal-organizer',
  email: 'ai-modal-organizer@example.test',
  fullName: 'AI Modal Organizer',
  phoneNumber: '0900000010',
  roles: ['ORGANIZER'],
  gender: 'MALE',
  isEmailVerified: true,
  profile: { fullName: 'AI Modal Organizer', phoneNumber: '0900000010' },
};

test('Smart AI dialog has a name and restores focus after Escape', async ({ page }) => {
  await page.addInitScript((user) => {
    localStorage.setItem('auth-storage', JSON.stringify({
      state: { user, isAuthenticated: true },
      version: 0,
    }));
  }, organizer);
  await page.route('**/api/v1/**', (route) => fulfillApi(route, { data: [] }));
  await page.goto('/organizer/tournaments/create', { waitUntil: 'domcontentloaded' });

  const openButton = page.getByRole('button', { name: /AI.*Excel/i });
  await expect(openButton).toBeVisible();
  await openButton.click();

  const dialog = page.getByRole('dialog');
  await expect(dialog).toBeVisible();
  await expect(dialog).toHaveAttribute('aria-modal', 'true');
  await expect(dialog.getByRole('button', { name: /close|đóng/i })).toBeVisible();
  await expect(dialog.getByRole('heading')).toBeVisible();

  await page.keyboard.press('Escape');

  await expect(dialog).toHaveCount(0);
  await expect(openButton).toBeFocused();
});
